ALTER TABLE public."Evaluation_Activities" ADD COLUMN template_snapshot jsonb;
CREATE OR REPLACE FUNCTION public.evaluation_capture_template() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE t public."Evaluation_Templates"; BEGIN IF NEW.template_id IS NOT NULL AND (TG_OP='INSERT' OR OLD.state='Draft') THEN SELECT * INTO t FROM public."Evaluation_Templates" WHERE id=NEW.template_id; IF NOT FOUND OR NOT t.active OR t.module<>NEW.module OR (t.starts_at IS NOT NULL AND NEW.starts_at<t.starts_at) OR (t.ends_at IS NOT NULL AND NEW.ends_at>t.ends_at) THEN RAISE EXCEPTION 'Template is inactive or outside its period'; END IF; IF cardinality(t.team_ids)>0 AND NOT NEW.team_ids<@t.team_ids THEN RAISE EXCEPTION 'Template audience mismatch'; END IF; NEW.template_snapshot:=to_jsonb(t); END IF; RETURN NEW; END $$;
CREATE TRIGGER evaluation_template_snapshot BEFORE INSERT OR UPDATE ON public."Evaluation_Activities" FOR EACH ROW EXECUTE FUNCTION public.evaluation_capture_template();
CREATE OR REPLACE FUNCTION public.evaluation_recurrence_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public."Evaluation_Activities"; period text; BEGIN SELECT * INTO a FROM public."Evaluation_Activities" WHERE id=NEW.activity_id; period:=a.template_snapshot->>'recurrence'; IF a.template_id IS NOT NULL AND period IN ('daily','weekly','monthly') THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id||a.template_id::text,0)); IF EXISTS(SELECT 1 FROM public."Evaluation_Results" r JOIN public."Evaluation_Activities" b ON b.id=r.activity_id WHERE r.user_id=NEW.user_id AND b.template_id=a.template_id AND date_trunc(CASE period WHEN 'daily' THEN 'day' WHEN 'weekly' THEN 'week' ELSE 'month' END,b.starts_at)=date_trunc(CASE period WHEN 'daily' THEN 'day' WHEN 'weekly' THEN 'week' ELSE 'month' END,a.starts_at)) THEN RAISE EXCEPTION 'Already evaluated in this template period'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER evaluation_recurrence_before BEFORE INSERT ON public."Evaluation_Results" FOR EACH ROW EXECUTE FUNCTION public.evaluation_recurrence_guard();
REVOKE ALL ON FUNCTION public.evaluation_capture_template(),public.evaluation_recurrence_guard() FROM PUBLIC,anon,authenticated;